<?php
declare(strict_types=1);
namespace Centro;
final class FinancialState
{
    public function __construct(private readonly \PDO $pdo) {}
    private function q(string $sql,array $args=[]):array{$s=$this->pdo->prepare($sql);$s->execute($args);return $s->fetchAll(\PDO::FETCH_ASSOC);}
    public function snapshot(string $environment):array{
        $owns=!$this->pdo->inTransaction();if($owns)$this->pdo->beginTransaction();
        try{$result=$this->readSnapshot($environment);if($owns)$this->pdo->commit();return $result;}
        catch(\Throwable $e){if($owns&&$this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    private function readSnapshot(string $environment):array{
        $migration=$this->q('SELECT checksum FROM schema_migrations WHERE version=?',['017_operational_completion']);
        $operational=isset($migration[0])&&hash_equals(hash_file('sha256',dirname(__DIR__).'/database/migrations/017_operational_completion.sql'),$migration[0]['checksum']);
        $sales=[];$lines=$this->q('SELECT sale_id,product_id,version_id,description,quantity,unit_price,line_total FROM fin_sale_lines WHERE environment_id=? ORDER BY sale_id,line_no',[$environment]);$by=[];foreach($lines as $l)$by[$l['sale_id']][]=$l;
        $rows=$this->q('SELECT s.*,COALESCE(a.collected,0) collected,COALESCE(r.refunded,0) refunded FROM fin_sales s LEFT JOIN (SELECT sale_id,SUM(amount) collected FROM fin_sale_allocations WHERE environment_id=? GROUP BY sale_id) a ON a.sale_id=s.id LEFT JOIN (SELECT sale_id,SUM(amount) refunded FROM fin_sale_revisions WHERE environment_id=? AND kind="refund_commercial" GROUP BY sale_id) r ON r.sale_id=s.id WHERE s.environment_id=? ORDER BY s.issued_on,s.created_at',[$environment,$environment,$environment]);
        foreach($rows as $s){$ls=$by[$s['id']]??[];$qty=$ls?array_sum(array_map(static fn($x)=>(float)$x['quantity'],$ls)):1;$unit=$ls?(float)$ls[0]['unit_price']:(float)$s['total'];$line=$ls[0]??[];$sales[]=['id'=>$s['id'],'createdAt'=>$s['created_at'],'type'=>'unica','date'=>$s['issued_on'],'productId'=>$line['product_id']??'','versionId'=>$line['version_id']??'','projectId'=>'','planId'=>'','subId'=>'','brandId'=>'','channelId'=>'','country'=>'','customerId'=>$s['customer_id']??'','concept'=>$line['description']??'','currency'=>$s['currency_id'],'qty'=>$qty,'unitPrice'=>$unit,'discount'=>0,'coupon'=>'','refunded'=>(float)$s['refunded'],'commission'=>0,'tax'=>0,'payStatus'=>bccomp((string)$s['collected'],(string)$s['total'],2)>=0?'cobrado':'pendiente','delivery'=>'no_aplica','status'=>$s['status'],'origin'=>'sql','source'=>'','externalId'=>'','notes'=>'','history'=>[]];}
        $expenses=[];foreach($this->q('SELECT e.* FROM fin_expenses e WHERE e.environment_id=? ORDER BY e.incurred_on,e.created_at',[$environment]) as $e)$expenses[]=['id'=>$e['id'],'createdAt'=>$e['created_at'],'concept'=>'Gasto','supplierId'=>$e['supplier_id']??'','category'=>'','amount'=>(float)$e['total'],'currency'=>$e['currency_id'],'date'=>$e['incurred_on'],'dueDate'=>'','frequency'=>'unico','status'=>$e['status'],'payDate'=>'','accountId'=>'','payMethod'=>'','nature'=>'gasto','costType'=>'general','resourceId'=>'','alloc'=>['mode'=>'general','targets'=>[]],'receipt'=>'','origin'=>'sql','notes'=>''];
        $treasury=[];foreach($this->q('SELECT m.* FROM fin_movements m WHERE m.environment_id=? ORDER BY m.movement_on,m.created_at',[$environment]) as $m)$treasury[]=['id'=>$m['id'],'date'=>$m['movement_on'],'type'=>$m['kind']==='receipt'?'cobro':($m['kind']==='payment'?'pago':($m['kind']==='refund'?'reembolso':(['transfer'=>'transferencia','capital_contribution'=>'aporte','withdrawal'=>'retiro','treasury_adjustment'=>'ajuste'][$m['kind']]??$m['kind']))),'accountFrom'=>$m['direction']==='out'?$m['account_id']:'','accountTo'=>$m['direction']==='in'?$m['account_id']:'','amount'=>(float)$m['amount'],'currency'=>$m['currency_id'],'saleId'=>$m['sale_id']??'','expenseId'=>$m['expense_id']??'','note'=>''];

        $notes=[];foreach($this->q('SELECT a.payload_json,r.result_json FROM fin_audit a JOIN fin_operation_receipts r ON r.environment_id=a.environment_id AND r.operation_id=a.operation_id WHERE a.environment_id=?',[$environment]) as $a){$cmd=json_decode($a['payload_json'],true);$result=json_decode($a['result_json'],true);foreach(['movement_id','source_movement_id','destination_movement_id'] as $key)if(isset($result[$key]))$notes[$result[$key]]=is_string($cmd['note']??null)?$cmd['note']:'';}
        foreach($treasury as &$t)$t['note']=$notes[$t['id']]??'';unset($t);
        $lastPayments=[];foreach($this->q('SELECT expense_id,movement_on,account_id FROM fin_movements WHERE environment_id=? AND kind="payment" ORDER BY movement_on,created_at,id',[$environment]) as $m)$lastPayments[$m['expense_id']]=$m;
        foreach($expenses as &$x){if($x['status']==='pagado'&&isset($lastPayments[$x['id']])){$x['payDate']=$lastPayments[$x['id']]['movement_on'];$x['accountId']=$lastPayments[$x['id']]['account_id'];}}unset($x);
        $meta=[];foreach(($operational?$this->q('SELECT * FROM fin_entity_metadata WHERE environment_id=?',[$environment]):[]) as $m)$meta[$m['entity_kind']][$m['entity_id']]=json_decode($m['record_json'],true,32,JSON_THROW_ON_ERROR);
        $versions=[];foreach($this->q('SELECT id,row_version,total FROM fin_sales WHERE environment_id=?',[$environment]) as $r)$versions[$r['id']]=$r;
        foreach($sales as &$sale){$sale=array_replace($sale,$meta['sale'][$sale['id']]??[]);$sale['_sqlVersion']=(int)$versions[$sale['id']]['row_version'];$sale['_sqlTotal']=$versions[$sale['id']]['total'];$sale['_sqlLines']=$by[$sale['id']]??[];}unset($sale);
        $exp=[];foreach($this->q('SELECT e.id,e.row_version,COALESCE(SUM(a.amount),0) paid FROM fin_expenses e LEFT JOIN fin_expense_allocations a ON a.environment_id=e.environment_id AND a.expense_id=e.id WHERE e.environment_id=? GROUP BY e.id,e.row_version',[$environment]) as $r)$exp[$r['id']]=$r;
        foreach($expenses as &$expense){$expense=array_replace($expense,$meta['expense'][$expense['id']]??[]);$expense['_sqlVersion']=(int)$exp[$expense['id']]['row_version'];$expense['_sqlPaid']=$exp[$expense['id']]['paid'];}unset($expense);
        // Original dates/history remain evidence, not new SQL events or cash.
        $historical=[];foreach($this->q('SELECT payload_json FROM fin_audit WHERE environment_id=? AND event IN ("sale_register","expense_register")',[$environment]) as $audit){$command=json_decode($audit['payload_json'],true,64,JSON_THROW_ON_ERROR);$group=$command['_historical']['group']??null;if(!is_string($group))continue;[$collection,$source]=array_pad(explode(':',$group,2),2,'');$original=$this->q('SELECT payload FROM original_financial_snapshots WHERE environment_id=? AND collection=? AND id=?',[$environment,$collection,$source]);if($original){$record=json_decode($original[0]['payload'],true,64,JSON_THROW_ON_ERROR);$historical[$collection][$record['id']]=$record;}}
        foreach($sales as &$sale){$original=$historical['sales'][$sale['id']]??[];foreach(['createdAt','history'] as $field)if(array_key_exists($field,$original))$sale[$field]=$original[$field];}unset($sale);
        foreach($expenses as &$expense){$original=$historical['expenses'][$expense['id']]??[];if(array_key_exists('createdAt',$original))$expense['createdAt']=$original['createdAt'];}unset($expense);
        $events=[];foreach($this->q($operational?'SELECT e.*,x.price_snapshot_id FROM subscription_events e LEFT JOIN fin_subscription_evidence x ON x.environment_id=e.environment_id AND x.event_id=e.id WHERE e.environment_id=? ORDER BY e.event_date,e.created_at,e.id':'SELECT e.*,NULL AS price_snapshot_id FROM subscription_events e WHERE e.environment_id=? ORDER BY e.event_date,e.created_at,e.id',[$environment]) as $v)$events[$v['subscription_id']][]=['id'=>$v['id'],'date'=>$v['event_date'],'type'=>$v['event_type'],'planId'=>$v['plan_id'],'amount'=>$v['amount']===null?null:(float)$v['amount'],'currency'=>$v['currency_id'],'saleId'=>$v['sale_id'],'note'=>$v['note'],'priceSnapshotId'=>$v['price_snapshot_id']];
        $subs=[];foreach($this->q('SELECT * FROM subscriptions WHERE environment_id=? AND archived_at IS NULL ORDER BY start_date,id',[$environment]) as $v)$subs[]=['id'=>$v['id'],'projectId'=>$v['project_id'],'planId'=>$v['plan_id'],'customerId'=>$v['customer_id'],'status'=>$v['status'],'startDate'=>$v['start_date'],'nextRenewal'=>$v['next_renewal'],'cancelDate'=>$v['cancel_date'],'externalId'=>$v['external_id'],'createdAt'=>$v['created_at'],'origin'=>'sql','events'=>$events[$v['id']]??[],'_sqlVersion'=>(int)$v['row_version'],'_overdue'=>$v['next_renewal']!==null&&$v['next_renewal']<gmdate('Y-m-d')&&in_array($v['status'],['activa','prueba','impaga'],true)];
        $prices=$this->q('SELECT id,plan_id,price,currency_id,period,valid_from,valid_to,provenance FROM plan_prices WHERE environment_id=? AND archived_at IS NULL',[$environment]);
        $balances=$this->q('SELECT a.id,a.currency_id,COALESCE(SUM(CASE m.direction WHEN "in" THEN m.amount ELSE -m.amount END),0) balance FROM accounts a LEFT JOIN fin_movements m ON m.environment_id=a.environment_id AND m.account_id=a.id WHERE a.environment_id=? GROUP BY a.id,a.currency_id',[$environment]);
        $customers=[];foreach($this->q('SELECT c.* FROM customers c WHERE c.environment_id=? AND (EXISTS(SELECT 1 FROM subscriptions s WHERE s.environment_id=c.environment_id AND s.customer_id=c.id) OR EXISTS(SELECT 1 FROM fin_sales s WHERE s.environment_id=c.environment_id AND s.customer_id=c.id))',[$environment]) as $c)$customers[]=['id'=>$c['id'],'name'=>$c['name'],'email'=>$c['email']??'','country'=>$c['country'],'createdAt'=>$c['business_date']??$c['created_at'],'notes'=>$c['notes'],'origin'=>$c['origin'],'consent'=>$c['consent']===null?null:(bool)$c['consent']];
        return ['sales'=>$sales,'expenses'=>$expenses,'treasury'=>$treasury,'subs'=>$subs,'planPrices'=>$prices,'balances'=>$balances,'subscriptionCustomers'=>$customers,'operationalReady'=>$operational];
    }
}
